/* PsychLogic — Foundational Mock 8 (Therapies & Psychometrics) question bank.
   Each item: { id, question(may contain structured A-R / PYQ badge / match table), options[4], correctAnswer(0-3), subject, explanation, examWatch } */
window.MOCK_QUESTIONS = [{"id": 1, "question": "<span class=\"pyq-badge\">PYQ · IHBAS 2024</span>The process in which the therapist directs his or her own unresolved feelings towards the client is termed as:", "options": ["Negative transference", "Counter transference", "Positive transference", "Negative counter transference"], "correctAnswer": 1, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Countertransference is the therapist’s emotional reaction to the client, shaped by the therapist’s own unresolved conflicts. Modern therapists also use it as information about the client.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Negative transference – the CLIENT’s hostile feelings towards the therapist.</li><li>Positive transference – the CLIENT’s affectionate feelings towards the therapist.</li><li>‘Negative countertransference’ is not the standard name for the general process.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Transference = client → therapist; countertransference = therapist → client.</li><li>Personal therapy and supervision help therapists manage countertransference.</li><li>Paula Heimann (1950) argued countertransference can be a useful tool, not just an obstacle.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 2, "question": "<span class=\"pyq-badge\">PYQ · JEMAS 2024</span>Which of the following is NOT based on operant conditioning?", "options": ["Contingency management", "Implosion", "Token economy", "Premack principle"], "correctAnswer": 1, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Implosion (Stampfl) is an exposure therapy in imagination, based on classical conditioning and extinction of fear. The other three work by managing consequences — operant conditioning.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Contingency management gives rewards for target behaviour (e.g. clean urine tests) — operant.</li><li>Token economy uses tokens as secondary reinforcers — operant.</li><li>Premack principle uses a preferred activity as a reinforcer — operant.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Implosion adds psychodynamic themes to imagined exposure; flooding usually uses the real situation.</li><li>Thomas Stampfl developed implosive therapy in the 1960s.</li><li>Both flooding and implosion start at high anxiety without relaxation.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 3, "question": "In REBT, ‘musturbation’ refers to:", "options": ["Exaggerating how terrible events are", "Believing one cannot stand discomfort", "Rigid demands such as ‘I must’ and ‘others should’", "Rating one’s whole self as worthless"], "correctAnswer": 2, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ellis coined ‘musturbation’ for absolute demands on oneself, others and the world (‘I must succeed’, ‘people must treat me fairly’). He saw these as the core of disturbance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Exaggerating how bad something is = awfulising.</li><li>‘I can’t stand it’ = low frustration tolerance.</li><li>Rating the whole self as worthless = global self-downing.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>NIMHANS 2023 (memory-based) asked about ‘awfulising’ and ‘musturbation’ in REBT.</li><li>Ellis encouraged unconditional self-acceptance instead of self-rating.</li><li>Disputing styles: logical, empirical and pragmatic.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — NIMHANS 2023 (memory-based). We recommend you keep this area ready."}, {"id": 4, "question": "Ravi, sober for 3 months, has one beer at a wedding, thinks ‘I’ve blown it, I’m a failure’, and goes on a three-day binge. In Marlatt’s relapse prevention model this reaction is the:", "options": ["Urge surfing", "High-risk situation", "Seemingly irrelevant decision", "Abstinence violation effect"], "correctAnswer": 3, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The abstinence violation effect is the guilt and ‘all is lost’ thinking after a lapse, which turns a single slip into a full relapse.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Seemingly irrelevant decisions are small choices that lead one closer to a high-risk situation.</li><li>The wedding itself is the high-risk situation, not his reaction to the lapse.</li><li>Urge surfing is a mindfulness skill for riding out cravings.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Marlatt and Gordon, Relapse Prevention (1985).</li><li>A lapse is a single slip; a relapse is a return to the old pattern.</li><li>Mindfulness-based relapse prevention (MBRP) adds meditation to the model.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 5, "question": "Research on ‘expressed emotion’ led to which family-based intervention for preventing relapse in schizophrenia?", "options": ["Psychoeducational family intervention", "Strategic paradoxical directives", "Classical psychoanalysis of the patient", "Gestalt empty-chair work"], "correctAnswer": 0, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Because high expressed emotion (criticism, hostility, emotional over-involvement) predicts relapse, family psychoeducation teaches families about the illness, coping and communication. It lowers relapse rates.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Psychoanalysis is not recommended for schizophrenia.</li><li>Gestalt techniques are not the evidence-based family approach here.</li><li>Paradoxical directives are not used for this purpose.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Brown, Birley and Wing linked EE to relapse; Vaughn and Leff confirmed it.</li><li>EE is measured with the Camberwell Family Interview.</li><li>NICE guidelines recommend family intervention for people with schizophrenia who live with or are in close contact with family.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 6, "question": "OARS — open questions, affirmations, reflections and summaries — are the core skills of:", "options": ["Motivational interviewing", "Systematic desensitisation", "Psychoanalysis", "Rational emotive behaviour therapy"], "correctAnswer": 0, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Motivational interviewing (Miller and Rollnick) uses OARS to explore ambivalence and draw out the client’s own reasons for change (‘change talk’).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Psychoanalysis uses free association and interpretation.</li><li>Systematic desensitisation uses relaxation and a fear hierarchy.</li><li>REBT uses disputing of irrational beliefs.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MI spirit: partnership, acceptance, compassion and evocation.</li><li>Change talk can be remembered as DARN-CAT (desire, ability, reasons, need; commitment, activation, taking steps).</li><li>MI is often combined with Prochaska and DiClemente’s stages of change.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IMHANS 2025, RML 2022. We recommend you keep this area ready."}, {"id": 7, "question": "Flooding differs from systematic desensitisation mainly because flooding:", "options": ["Relies on positive reinforcement", "Is done only in imagination", "Starts at high anxiety without relaxation", "Uses relaxation to block anxiety"], "correctAnswer": 2, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In flooding, the person is exposed at once to the most feared situation (usually in real life) and stays until anxiety falls. Systematic desensitisation climbs a graded hierarchy while relaxed.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Using relaxation describes systematic desensitisation.</li><li>Flooding is usually in vivo; imagined high-intensity exposure is implosion.</li><li>Exposure methods work through extinction, not positive reinforcement.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Escape during flooding can strengthen fear, so sessions must continue until anxiety drops.</li><li>Graded exposure lies between the two.</li><li>Exposure is the common active ingredient in treating phobias.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>11 of them</b> (recent examples: IHBAS 2025, RML 2024, JEMAS 2024, NFSU 2023). We recommend you focus on this area."}, {"id": 8, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2021</span>The steepness or slope of the item characteristic curve gives information about:", "options": ["Difficulty value of the item", "Discriminating power of the item", "Effectiveness of distractors of the item", "None of the above"], "correctAnswer": 1, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In IRT, the slope of the item characteristic curve (the ‘a’ parameter) shows how sharply the item separates people just below and just above its difficulty level — its discrimination.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Difficulty (‘b’) is the curve’s location — the ability level at which the probability of a correct answer is 0.5.</li><li>Distractor analysis is part of classical item analysis.</li><li>There is a correct answer among the options.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The lower asymptote of the curve is the guessing (‘c’) parameter.</li><li>A flat curve means the item discriminates poorly.</li><li>IMHANS 2025 asked what IRT aims to do.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 9, "question": "Match the psychodynamic concept (List I) with the theorist (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Projective identification</td><td>a. Otto Kernberg</td></tr><tr><td>2. Selfobject</td><td>b. Michael Balint</td></tr><tr><td>3. Borderline personality organisation</td><td>c. Melanie Klein</td></tr><tr><td>4. The basic fault</td><td>d. Heinz Kohut</td></tr></tbody></table></div>", "options": ["1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a", "1-a, 2-d, 3-c, 4-b", "1-c, 2-d, 3-a, 4-b"], "correctAnswer": 3, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Klein described projective identification. Kohut introduced the selfobject. Kernberg described borderline personality organisation. Balint wrote The Basic Fault (1968).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Klein with Kohut, or Kernberg with Balint.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JANAS and JEMAS 2024 asked who gave ‘borderline personality organisation’.</li><li>Kernberg developed transference-focused psychotherapy (TFP).</li><li>Klein’s play technique used children’s play as an equivalent of free association.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — RML 2024, JEMAS 2024, RML 2022, JEMAS 2022, JANAS. We recommend you keep this area ready."}, {"id": 10, "question": "The ‘miracle question’ is a technique of:", "options": ["Solution-focused brief therapy", "Strategic family therapy", "Reality therapy", "Narrative therapy"], "correctAnswer": 0, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Steve de Shazer and Insoo Kim Berg’s solution-focused brief therapy asks: ‘If a miracle happened tonight and your problem was solved, what would be different tomorrow?’ It shifts focus to goals and solutions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Narrative therapy externalises the problem and re-authors stories.</li><li>Reality therapy uses WDEP and choice theory.</li><li>Strategic therapy uses directives and paradox.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other SFBT tools: exception questions, scaling questions, coping questions.</li><li>SFBT developed at the Brief Family Therapy Center, Milwaukee.</li><li>SFBT focuses on strengths, not on the history of the problem.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 11, "question": "<span class=\"pyq-badge\">PYQ · JEMAS 2022 &amp; JEMAS 2024</span>Replacing the fragmented self with the cohesive self is the primary developmental and therapeutic goal of:", "options": ["Kernberg", "Kohut", "Malan", "Horowitz"], "correctAnswer": 1, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Heinz Kohut’s self psychology sees many problems (especially narcissistic ones) as a fragile, ‘fragmented’ self. Through the therapist’s empathic attunement and selfobject transferences, the client builds a stable, cohesive self.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Kernberg – borderline personality organisation and transference-focused psychotherapy.</li><li>Malan – brief dynamic psychotherapy (triangle of conflict, triangle of person).</li><li>Horowitz – stress response syndromes and ‘person schemas’ in brief dynamic therapy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Kohut’s three selfobject transferences: mirroring, idealising and twinship (alter-ego).</li><li>Kohut, The Analysis of the Self (1971); The Restoration of the Self (1977).</li><li>Kohut saw narcissism as a developmental arrest; Kernberg saw it as a pathological defensive structure.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 12, "question": "<span class=\"pyq-badge\">PYQ · JEMAS 2022</span>Which of the following clinical procedure/s is/are NOT based on classical conditioning? 1. Flooding  2. Transference  3. Client-centred therapy  4. Systematic desensitisation", "options": ["1 only", "2 and 3 only", "1, 2 and 3 only", "1, 3 and 4 only"], "correctAnswer": 1, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Flooding and systematic desensitisation are exposure methods based on classical conditioning (extinction and counterconditioning). Transference is a psychoanalytic concept and client-centred therapy is humanistic — neither is based on classical conditioning.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>‘1 only’ wrongly calls flooding non-classical.</li><li>‘1, 2 and 3’ wrongly includes flooding.</li><li>‘1, 3 and 4’ includes flooding and desensitisation, which ARE classical-conditioning methods.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Aversion therapy and covert sensitisation are also classical-conditioning methods.</li><li>Token economy, shaping and response cost are operant methods.</li><li>IHBAS 2025 asked for the hallmark of behaviour therapy (classical/operant conditioning techniques).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 13, "question": "In factor analysis, the Kaiser (Kaiser–Guttman) criterion retains factors with:", "options": ["Eigenvalues less than 1", "Loadings greater than 0.30", "Communalities greater than 0.50", "Eigenvalues greater than 1"], "correctAnswer": 3, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> An eigenvalue shows how much total variance a factor explains. A factor with an eigenvalue above 1 explains more than a single original variable, so Kaiser’s rule keeps it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>0.30 is a common cut-off for a ‘salient’ loading, not for retaining factors.</li><li>Communality is the share of a variable’s variance explained by all factors.</li><li>Factors with eigenvalues below 1 are dropped.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>NIMHANS 2023 (memory-based) asked about the scree plot, which plots eigenvalues.</li><li>Parallel analysis (Horn) is now considered more accurate than Kaiser’s rule.</li><li>Factor loading = correlation between a variable and a factor.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IMHANS 2025, RINPAS 2024, NIMHANS 2023 (memory-based), IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 14, "question": "Biofeedback, in which a person learns to control heart rate or muscle tension by watching a monitor, is mainly based on:", "options": ["Classical conditioning", "Psychoanalytic insight", "Operant conditioning", "Cognitive restructuring"], "correctAnswer": 2, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The monitor signal acts as feedback that reinforces small changes in the right direction, so control of the body response is learnt through operant conditioning.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Classical conditioning pairs stimuli; biofeedback reinforces responses.</li><li>No unconscious material is involved.</li><li>Biofeedback trains bodily responses directly, not thoughts.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 asked for the name of the procedure in which people learn to control heart rate and body temperature (biofeedback).</li><li>Neal Miller showed operant control of autonomic responses in animals.</li><li>EMG biofeedback is used for tension headache; EEG biofeedback is called neurofeedback.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — JEMAS 2024, GMCH 2023, Gurugram. We recommend you keep this area ready."}, {"id": 15, "question": "The semantic differential, which rates concepts on bipolar adjectives along evaluation, potency and activity, was developed by:", "options": ["George Kelly", "Emory Bogardus", "Charles Osgood", "Louis Thurstone"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Osgood, Suci and Tannenbaum (1957) measured the connotative meaning of concepts with pairs like good–bad (evaluation), strong–weak (potency) and active–passive (activity).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Bogardus – social distance scale.</li><li>Thurstone – equal-appearing intervals.</li><li>Kelly – Role Construct Repertory Test.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IMHANS 2025 had ‘attitudes based on ratings along bipolar adjective pairs’ as an option.</li><li>Usually 7-point scales between the two adjectives.</li><li>Evaluation is the factor that explains the most variance.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2025. We recommend you keep this area ready."}, {"id": 16, "question": "According to Viktor Frankl, meaning in life can be found through all of the following values, EXCEPT:", "options": ["Instinctual values — satisfying basic drives", "Attitudinal values — the stand we take towards unavoidable suffering", "Experiential values — what we receive from the world", "Creative values — what we give to the world"], "correctAnswer": 0, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Frankl described three routes to meaning: creative (work, deeds), experiential (love, beauty, nature) and attitudinal (the attitude we choose towards suffering we cannot change). Drive satisfaction is the Freudian ‘will to pleasure’ he rejected.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Creative values are one of Frankl’s three.</li><li>Experiential values are one of Frankl’s three.</li><li>Attitudinal values are one of Frankl’s three — the most important in suffering.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Frankl: ‘will to meaning’ vs Freud’s ‘will to pleasure’ and Adler’s ‘will to power’.</li><li>Existential vacuum and noögenic neurosis come from lack of meaning.</li><li>JEMAS 2022 asked who developed logotherapy (Frankl).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: RML 2024, JEMAS 2024, NFSU 2023, JEMAS 2022). We recommend you focus on this area."}, {"id": 17, "question": "Arrange these therapies in the order in which they were introduced: I. Acceptance and commitment therapy II. Wolpe’s systematic desensitisation III. Ellis’s rational therapy (RT/RET) IV. Beck’s cognitive therapy", "options": ["II, III, IV, I", "III, IV, II, I", "II, IV, III, I", "III, II, IV, I"], "correctAnswer": 3, "subject": "Therapy research & history", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ellis introduced rational therapy in 1955; Wolpe published systematic desensitisation in 1958; Beck developed cognitive therapy in the 1960s; ACT developed through the 1980s and was published as a book in 1999.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Wolpe (1958) came after Ellis (1955); Beck came after both; ACT is the most recent.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>First wave = behaviour therapy; second wave = cognitive therapy; third wave = acceptance and mindfulness therapies.</li><li>Steven Hayes coined ‘third wave’ in 2004.</li><li>GMCH 2023 asked who first developed cognitive behaviour therapy.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>12 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, JEMAS 2024, NIMHANS 2023 (memory-based). We recommend you focus on this area."}, {"id": 18, "question": "In Likert’s method of summated ratings, a person’s attitude score is:", "options": ["The total of the ratings across all items", "The point where agreement switches to disagreement", "The ratings on bipolar adjective pairs", "The median scale value of the statements endorsed"], "correctAnswer": 0, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rensis Likert (1932) had people rate their agreement with each statement (e.g. 1–5) and summed the ratings — hence ‘summated ratings’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The median scale value of endorsed statements is Thurstone’s scoring.</li><li>The switch point from agreeing to disagreeing fits Guttman’s cumulative scale.</li><li>Bipolar adjective pairs are the semantic differential.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Likert scales need item analysis to select items that correlate with the total.</li><li>Likert data are ordinal, though often treated as interval.</li><li>RINPAS 2024 asked which measurement scales attitude scales use.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — GBU 2025, RINPAS 2024, RML 2022. We recommend you keep this area ready."}, {"id": 19, "question": "A 9-year-old with a hair-pulling habit is taught to notice the urge and clench his fists for a minute instead, with his parents praising each success. This is:", "options": ["Covert sensitisation", "Flooding", "Habit reversal training", "Thought stopping"], "correctAnswer": 2, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Habit reversal training (Azrin and Nunn, 1973) uses awareness training, a competing response (e.g. clenching fists), and social support or reinforcement. It is first-line for tics, trichotillomania and skin picking.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Thought stopping interrupts unwanted thoughts (e.g. saying ‘Stop!’).</li><li>Covert sensitisation pairs the behaviour with imagined unpleasant results.</li><li>Flooding is prolonged exposure to a feared stimulus.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>CBIT (comprehensive behavioural intervention for tics) is built on habit reversal.</li><li>Trichotillomania is in the DSM-5 obsessive-compulsive and related disorders chapter.</li><li>A competing response must be physically incompatible with the habit.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 20, "question": "A test correlates 0.40 with a criterion. The test’s reliability is 0.64 and the criterion’s reliability is 0.81. Using the correction for attenuation, the estimated true correlation is about:", "options": ["0.32", "0.56", "0.49", "0.62"], "correctAnswer": 1, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Corrected r = r ÷ √(r_xx × r_yy) = 0.40 ÷ √(0.64 × 0.81) = 0.40 ÷ (0.8 × 0.9) = 0.40 ÷ 0.72 ≈ 0.56.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>0.32 = 0.40 × 0.8 (multiplied instead of divided).</li><li>0.49 = 0.40 ÷ 0.81 (used only the criterion reliability, without the square root).</li><li>0.62 = 0.40 ÷ 0.64 (used only the test reliability, without the square root).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Spearman proposed the correction for attenuation (1904).</li><li>A validity coefficient cannot exceed the square root of the test’s reliability.</li><li>Low reliability ‘attenuates’ (weakens) observed correlations.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 21, "question": "During analysis, a client keeps arriving late, forgets sessions and changes the subject whenever her father is mentioned. In psychoanalytic terms this is:", "options": ["Acting out", "Working through", "Transference", "Resistance"], "correctAnswer": 3, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Resistance is anything the client does, usually unconsciously, to avoid painful material — lateness, forgetting, silence or changing the topic. Analysing it is a core psychoanalytic technique.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Transference – feelings from past figures redirected onto the therapist.</li><li>Acting out – expressing unconscious conflicts through actions outside therapy instead of talking about them.</li><li>Working through – the gradual process of turning insight into lasting change.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RINPAS 2024 asked what analysis of resistance means in psychodynamic therapy.</li><li>Freud saw resistance as the ego’s defences operating in therapy.</li><li>Interpretation of resistance usually comes before interpretation of content.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RINPAS 2024. We recommend you keep this area ready."}, {"id": 22, "question": "A Guttman (scalogram) scale is ‘cumulative’. This means that:", "options": ["Items are rated on 7-point bipolar adjective scales", "Each item has equal weight and ratings are summed", "Agreeing with a stronger item implies agreeing with all milder items", "Judges assign scale values to each item in advance"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In a perfect Guttman scale, items are ordered by intensity: anyone who agrees with an extreme item also agrees with all less extreme ones. The coefficient of reproducibility (≥ 0.90) checks this.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Equal-weight summing is Likert.</li><li>Bipolar adjectives are the semantic differential.</li><li>Judge-assigned values are Thurstone.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bogardus’ social distance scale is a classic cumulative scale.</li><li>Guttman scaling is a forerunner of IRT ideas.</li><li>Louis Guttman also developed facet theory.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RML 2022, MP ENT. We recommend you keep this area ready."}, {"id": 23, "question": "Irvin Yalom described four ‘ultimate concerns’ of existence. They are:", "options": ["Death, freedom, isolation and meaninglessness", "Freedom, responsibility, choice and hope", "Being, nothingness, anxiety and despair", "Death, guilt, anxiety and loneliness"], "correctAnswer": 0, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In Existential Psychotherapy (1980), Yalom said inner conflict comes from facing four givens: death, freedom (and responsibility), existential isolation, and meaninglessness.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Guilt and anxiety are reactions, not Yalom’s four givens.</li><li>Responsibility and choice are part of ‘freedom’, not separate givens.</li><li>‘Being and nothingness’ is Sartre’s book title, not Yalom’s list.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 listed Yalom among existential names.</li><li>Yalom also wrote The Theory and Practice of Group Psychotherapy.</li><li>Existential anxiety is seen as normal, not a disorder.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: IMHANS 2025, JEMAS 2024, JEMAS 2022, M.Phil Entrance 2021). We recommend you focus on this area."}, {"id": 24, "question": "Eye movement desensitisation and reprocessing (EMDR) was developed by:", "options": ["Patricia Resick", "Edna Foa", "Judith Herman", "Francine Shapiro"], "correctAnswer": 3, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Francine Shapiro introduced EMDR in 1987–89. The client holds a traumatic memory in mind while following bilateral stimulation, such as side-to-side eye movements.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Edna Foa – prolonged exposure therapy for PTSD.</li><li>Patricia Resick – cognitive processing therapy.</li><li>Judith Herman – described complex PTSD (Trauma and Recovery, 1992).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>EMDR has eight phases.</li><li>WHO (2013) recommends EMDR and trauma-focused CBT for PTSD.</li><li>Whether the eye movements themselves add benefit is still debated.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RML 2022. We recommend you keep this area ready."}, {"id": 25, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2025</span>‘Item Response Theory (IRT)’ in psychological testing is an advanced approach that aims to:", "options": ["Calculate a single score for each test taker", "Model the relationship between an individual’s ability and their probability of answering an item correctly", "Determine the reliability of a test using Cronbach’s alpha", "Establish norms for a test based on a representative sample"], "correctAnswer": 1, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> IRT models the probability of a correct (or keyed) response as a function of the person’s latent trait (θ) and item characteristics such as difficulty and discrimination.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Calculating a total score is classical test theory.</li><li>Cronbach’s alpha is a classical reliability index.</li><li>Norming is part of standardisation, not the aim of IRT.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IRT models: 1-parameter (Rasch: difficulty), 2-parameter (+ discrimination), 3-parameter (+ guessing).</li><li>Item parameters in IRT are ‘sample-invariant’ — a key advantage over classical test theory.</li><li>IRT makes computerised adaptive testing possible.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 26, "question": "Problem-solving therapy was first developed by:", "options": ["Mahoney and Thoresen", "Beck and Emery", "Meichenbaum and Goodman", "D’Zurilla and Goldfried"], "correctAnswer": 3, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Thomas D’Zurilla and Marvin Goldfried (1971) described problem-solving training: problem orientation, defining the problem, generating alternatives, decision-making, and putting the solution into practice and checking it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Meichenbaum and Goodman – self-instructional training.</li><li>Beck and Emery – cognitive therapy of anxiety disorders.</li><li>Mahoney and Thoresen – behavioural self-control.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Arthur Nezu later extended problem-solving therapy for depression.</li><li>Problem-solving therapy is used in primary care and with older adults.</li><li>‘Brainstorming’ is used in the generation-of-alternatives step.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 27, "question": "The concepts of the ‘good-enough mother’ and the ‘holding environment’, used widely in psychodynamic therapy, were given by:", "options": ["Ronald Fairbairn", "Melanie Klein", "Donald Winnicott", "Margaret Mahler"], "correctAnswer": 2, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Winnicott taught that a ‘good-enough’ (not perfect) mother provides a ‘holding environment’ in which the infant’s self can grow. Therapists try to offer a similar holding environment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Klein – paranoid-schizoid and depressive positions, projective identification.</li><li>Mahler – separation-individuation phases.</li><li>Fairbairn – humans are object-seeking rather than pleasure-seeking.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2022 asked who gave the concept of the transitional object (Winnicott).</li><li>Winnicott also described the ‘true self’ and ‘false self’.</li><li>Object relations theory focuses on internalised relationships, not drives.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — NIMHANS 2023 (memory-based), JEMAS 2022. We recommend you keep this area ready."}, {"id": 28, "question": "Mindfulness-based cognitive therapy (MBCT) was developed mainly to:", "options": ["Prevent relapse in recurrent depression", "Improve attention in childhood ADHD", "Reduce self-harm in borderline personality", "Treat acute psychosis"], "correctAnswer": 0, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Segal, Williams and Teasdale (2002) developed MBCT to help people who had recovered from repeated depression notice and step back from negative thinking, reducing relapse.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>It is not a treatment for acute psychosis.</li><li>Self-harm in borderline personality is treated mainly with DBT.</li><li>It was not designed for ADHD.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MBCT roughly halves relapse risk in people with three or more past episodes.</li><li>MBCT is an 8-week group programme based on MBSR.</li><li>‘Decentering’ — seeing thoughts as mental events — is its key mechanism.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, RINPAS 2024, JEMAS 2024). We recommend you focus on this area."}, {"id": 29, "question": "The scree test for deciding how many factors to keep was proposed by:", "options": ["Raymond Cattell", "Henry Kaiser", "Louis Thurstone", "Charles Spearman"], "correctAnswer": 0, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Raymond Cattell (1966) suggested plotting eigenvalues and keeping the factors above the ‘elbow’, where the steep slope turns into a flat ‘scree’ (rubble at the foot of a cliff).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Kaiser – the eigenvalue-greater-than-1 rule and varimax rotation.</li><li>Thurstone – multiple factor analysis and ‘simple structure’.</li><li>Spearman – the two-factor theory and early factor analysis.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>NIMHANS 2023 (memory-based) asked in which technique a scree plot is used.</li><li>Cattell used factor analysis to build the 16PF.</li><li>IMHANS 2021 asked which strategy the 16PF is based on (factor analysis).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — NIMHANS 2023 (memory-based). We recommend you keep this area ready."}, {"id": 30, "question": "<span class=\"pyq-badge\">PYQ · IHBAS 2025</span>In the A-B-C-D-E model of cognitive behaviour therapy (RET), ‘D’ refers to:", "options": ["Drama", "Desensitization", "Discuss", "Disputing"], "correctAnswer": 3, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In Ellis’s model: A = activating event, B = belief, C = emotional/behavioural consequence, D = disputing irrational beliefs, E = effective new philosophy (new effect).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Drama, desensitisation and ‘discuss’ are not part of the model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS 2025 also asked who developed REBT (Albert Ellis).</li><li>Ellis renamed RET as REBT in 1993.</li><li>IMHANS 2025 asked what REBT says causes distress (irrational beliefs).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 31, "question": "When a test’s regression weights are tried on a new sample, the validity coefficient usually drops. This is called:", "options": ["Regression towards the mean", "Shrinkage", "Attenuation", "Restriction of range"], "correctAnswer": 1, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Cross-validation tests a prediction equation on a fresh sample. Because the original weights partly fitted chance features of the first sample, validity ‘shrinks’ in the new one.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Attenuation is lowering of a correlation by measurement unreliability.</li><li>Restriction of range lowers a correlation when the sample’s scores vary too little.</li><li>Regression to the mean is the tendency of extreme scores to move towards the average on retest.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Shrinkage is greater with small samples and many predictors.</li><li>Adjusted R2 estimates shrinkage.</li><li>Cross-validation is a key step in test construction.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 32, "question": "The Premack principle states that:", "options": ["A less probable behaviour can reinforce a more probable one", "Punishment works best when it is immediate", "A more probable behaviour can reinforce a less probable one", "Any stimulus paired with food becomes a reinforcer"], "correctAnswer": 2, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> David Premack (1959): access to a high-frequency (preferred) activity can reinforce a low-frequency one — ‘first finish homework, then play cricket’ (‘Grandma’s rule’).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The direction is reversed.</li><li>A stimulus paired with food becomes a conditioned (secondary) reinforcer — a different idea.</li><li>Timing of punishment is a separate principle.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 included the Premack principle among operant methods.</li><li>Response deprivation theory (Timberlake and Allison) later refined it.</li><li>Used widely in classrooms and parent training.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — JEMAS 2024, GMCH 2023, JEMAS 2022, M.Phil Entrance 2021. We recommend you keep this area ready."}, {"id": 33, "question": "In Rogers’ person-centred therapy, ‘congruence’ means the therapist is:", "options": ["Accepting the client without conditions", "Directive in setting therapy goals", "Accurately sensing the client’s inner world", "Genuine — inner experience matches what is expressed"], "correctAnswer": 3, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Congruence (genuineness) means the therapist is real, not hiding behind a professional role — what they feel and what they show match.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Accepting without conditions = unconditional positive regard.</li><li>Sensing the client’s inner world = accurate empathic understanding.</li><li>Person-centred therapy is non-directive.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RINPAS 2024 asked for the central tenet of client-centred therapy (all three core conditions).</li><li>IHBAS 2024 asked for the critical feature of Rogers’ therapy (unconditional positive regard).</li><li>Rogers (1957) listed six necessary and sufficient conditions for change.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>15 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, RML 2024, RINPAS 2024). We recommend you focus on this area."}, {"id": 34, "question": "At her appraisal Riya gets ten positive comments and one minor criticism. She leaves thinking only about the criticism and feels she has failed. This is:", "options": ["Overgeneralisation", "Selective abstraction", "Personalisation", "Magnification"], "correctAnswer": 1, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Selective abstraction (mental filter) means focusing on one detail taken out of context and ignoring the rest of the evidence.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Overgeneralisation – drawing a broad rule from one event (‘I always fail’).</li><li>Magnification – blowing the importance of something out of proportion.</li><li>Personalisation – blaming oneself for events not under one’s control.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other Beck distortions: arbitrary inference, dichotomous thinking, minimisation.</li><li>JEMAS 2022 and JEMAS 2024 asked what Beck’s cognitive triad is (self, world, future).</li><li>Burns popularised these as ‘cognitive distortions’ in Feeling Good (1980).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, JEMAS 2024, IHBAS 2024). We recommend you focus on this area."}, {"id": 35, "question": "In Eric Berne’s transactional analysis, a ‘crossed transaction’ occurs when:", "options": ["A hidden psychological message lies behind the social one", "Both people speak Adult-to-Adult", "The reply comes from an unexpected ego state, so communication breaks down", "A person repeatedly plays the same ‘game’"], "correctAnswer": 2, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In a crossed transaction, the response does not come from the ego state that was addressed (e.g. Adult question, angry Parent reply), so communication stops or turns into conflict.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Adult-to-Adult exchange is a complementary transaction.</li><li>A hidden message behind a social one is an ulterior transaction.</li><li>Repeated hidden patterns with a payoff are ‘games’ (Games People Play, 1964).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Three ego states: Parent, Adult, Child (PAC).</li><li>Life positions: ‘I’m OK – You’re OK’ is the healthy one (Thomas Harris popularised it).</li><li>Scripts are unconscious life plans formed in childhood.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IMHANS 2025, RML 2024, RML 2022, JANAS, Gurugram. We recommend you keep this area ready."}, {"id": 36, "question": "Covert sensitisation, in which the client imagines an unpleasant consequence together with the unwanted behaviour, was developed by:", "options": ["Joseph Cautela", "Joseph Wolpe", "Thomas Stampfl", "Nathan Azrin"], "correctAnswer": 0, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Joseph Cautela (1967) developed covert sensitisation — aversion therapy done in imagination, e.g. imagining nausea while reaching for a drink.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Wolpe – systematic desensitisation.</li><li>Stampfl – implosive therapy.</li><li>Azrin – token economy (with Ayllon) and habit reversal (with Nunn).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cautela also described covert reinforcement and covert modelling.</li><li>Aversion therapy pairs the behaviour with a real unpleasant stimulus (e.g. disulfiram, mild shock).</li><li>Aversive methods raise ethical concerns and are now rarely used.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — JEMAS 2024, JANAS. We recommend you keep this area ready."}, {"id": 37, "question": "Gestalt therapy’s ‘top dog–underdog’ refers to:", "options": ["Dominant and submissive members of a family", "The power gap between therapist and client", "The Parent and Child ego states in transactional analysis", "An inner conflict between the demanding ‘should’ side and the resisting, excuse-making side"], "correctAnswer": 3, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Fritz Perls described the ‘top dog’ (critical, demanding, like a harsh conscience) and the ‘underdog’ (whining, making excuses, sabotaging). Gestalt work, such as two-chair dialogue, helps integrate them.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>It is about parts inside one person, not the therapist–client relationship.</li><li>Parent and Child ego states belong to Eric Berne’s transactional analysis.</li><li>It is not a family-hierarchy idea.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS 2025 asked which therapy uses the empty chair technique (Gestalt).</li><li>Other Gestalt ideas: unfinished business, awareness, ‘here and now’, contact boundaries.</li><li>Perls’ famous ‘Gestalt prayer’: ‘I do my thing and you do your thing...’.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: IHBAS 2025, JEMAS 2024, JEMAS 2022, M.Phil Entrance 2021). We recommend you focus on this area."}, {"id": 38, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2025</span>‘Mindfulness-Based Stress Reduction (MBSR)’ incorporates elements from:", "options": ["Sufism", "Integral Yoga", "Buddhism", "Bhagavad Gita"], "correctAnswer": 2, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Jon Kabat-Zinn developed MBSR (1979, University of Massachusetts) as an 8-week programme drawing on Buddhist mindfulness (vipassana and Zen) meditation, presented in a secular form.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Sufism – Islamic mysticism; not the basis of MBSR.</li><li>Integral Yoga – Sri Aurobindo’s system; MBSR uses some yoga postures, but its core is Buddhist mindfulness.</li><li>The Bhagavad Gita is a Hindu text; not the source of MBSR.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Kabat-Zinn defines mindfulness as paying attention on purpose, in the present moment, non-judgementally.</li><li>MBCT combines MBSR with cognitive therapy for depression relapse.</li><li>Vipassana (insight meditation) is taught widely in India.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 39, "question": "All of the following are features of Beck’s cognitive therapy, EXCEPT:", "options": ["Homework assignments", "Interpretation of the transference neurosis", "Setting an agenda in each session", "Socratic questioning"], "correctAnswer": 1, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Cognitive therapy is structured, present-focused and collaborative, with agendas, homework and Socratic questioning. Interpreting the transference neurosis belongs to psychoanalysis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Homework is a core part of cognitive therapy.</li><li>Socratic questioning is its main questioning style.</li><li>Each session has an agreed agenda.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Beck trained as a psychoanalyst before developing cognitive therapy in the 1960s.</li><li>Cognitive Therapy of Depression (Beck, Rush, Shaw and Emery, 1979).</li><li>RINPAS 2024 asked what CBT works on (thoughts and behaviour).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>11 of them</b> (recent examples: IHBAS 2025, GBU 2025, JEMAS 2024, NIMHANS 2023 (memory-based). We recommend you focus on this area."}, {"id": 40, "question": "To treat a snake phobia, the therapist first handles the snake herself, then guides the client step by step to touch it with her support. This is:", "options": ["Participant modelling", "Flooding", "Covert modelling", "Shaping"], "correctAnswer": 0, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Participant (guided) modelling, studied by Bandura, combines watching a model with guided, graded practice by the client. It was highly effective for snake phobia.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Covert modelling – imagining someone else coping.</li><li>Shaping reinforces small steps but has no model.</li><li>Flooding exposes the person to maximum fear at once, without gradual steps.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bandura, Blanchard and Ritter (1969) compared modelling methods for snake phobia.</li><li>Modelling works through observational learning and self-efficacy.</li><li>JEMAS 2024 asked about Bandura and observational learning.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>14 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, JEMAS 2024). We recommend you focus on this area."}, {"id": 41, "question": "In classical psychoanalysis, the ‘fundamental rule’ asks the patient to:", "options": ["Say whatever comes to mind without censoring it", "Lie on the couch facing away from the analyst", "Avoid contact with the analyst outside sessions", "Report every dream at the next session"], "correctAnswer": 0, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The fundamental rule is free association: the patient reports every thought, however embarrassing or irrelevant, so that unconscious material can surface.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The couch is a setting arrangement, not the fundamental rule.</li><li>Avoiding outside contact relates to boundaries, not the fundamental rule.</li><li>Dreams are analysed, but reporting them is not ‘the fundamental rule’.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2022 asked who coined ‘free association’ (Freud).</li><li>Freud called dreams ‘the royal road to the unconscious’.</li><li>Analytic neutrality and abstinence are the analyst’s matching rules.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IHBAS 2025, GBU 2025, RML 2022, JEMAS 2022. We recommend you keep this area ready."}, {"id": 42, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Gestalt therapy emphasises awareness of the ‘here and now’.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">Fritz Perls was originally trained as a psychoanalyst.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 1, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both statements are true, but R does not explain A. Perls did train in psychoanalysis, but Gestalt therapy’s focus on present awareness came from his reaction against analysis of the past, and from Gestalt psychology and existentialism.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A is wrong because R does not explain A.</li><li>C and D are wrong because both statements are true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Perls, Hefferline and Goodman wrote Gestalt Therapy (1951); Laura Perls co-founded the approach.</li><li>IHBAS 2025 asked which therapy uses the empty chair technique.</li><li>IHBAS 2025 also asked for a general goal of humanistic-experiential therapy.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: IHBAS 2025, JEMAS 2024, JEMAS 2022, M.Phil Entrance 2021). We recommend you focus on this area."}, {"id": 43, "question": "<span class=\"pyq-badge\">PYQ · IHBAS 2024</span>Exposure and response prevention works on the principle of:", "options": ["Counter conditioning", "Habituation and extinction", "Reciprocal inhibition", "Graded exposure"], "correctAnswer": 1, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In ERP, staying with the trigger without performing the ritual lets anxiety fall on its own (habituation), and the link between trigger and fear weakens because the feared outcome does not happen (extinction).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Counterconditioning pairs the feared stimulus with an incompatible response (e.g. relaxation).</li><li>Reciprocal inhibition is Wolpe’s principle behind systematic desensitisation.</li><li>Graded exposure is a way of doing exposure, not the underlying principle.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ERP was pioneered by Victor Meyer (1966) and developed by Edna Foa.</li><li>Modern ‘inhibitory learning’ theory says extinction builds a new safety memory.</li><li>JEMAS 2024 and RML 2024 asked which disorder ERP is used for (OCD).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 44, "question": "<span class=\"pyq-badge\">PYQ · JEMAS 2022</span>Which of the following names is NOT associated with existential therapy?", "options": ["Rollo May", "Sandor Ferenczi", "Karl Jaspers", "R.D. Laing"], "correctAnswer": 1, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Sandor Ferenczi was a Hungarian psychoanalyst, a close colleague of Freud, known for ‘active technique’ and mutual analysis. The others are existential thinkers or therapists.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Rollo May brought existential psychology to the USA (The Meaning of Anxiety, 1950).</li><li>Karl Jaspers – existential philosopher and psychiatrist (General Psychopathology, 1913).</li><li>R.D. Laing – existential psychiatrist (The Divided Self, 1960).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 asked a similar question with Walter Mischel as the odd one out.</li><li>Other existential names: Binswanger, Boss, Yalom, Frankl, van Deurzen.</li><li>Existential therapy focuses on freedom, responsibility, meaning and death.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 45, "question": "Generalizability theory (Cronbach and colleagues) differs from classical test theory because it:", "options": ["Treats all error as one undifferentiated term", "Does not deal with reliability at all", "Splits error into separate sources such as raters, occasions and items", "Uses only item difficulty to judge a test"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> G-theory uses analysis of variance to estimate how much each ‘facet’ (raters, occasions, items, etc.) contributes to error, and then how to design a more dependable measurement (decision or D-study).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Treating error as a single term is classical test theory.</li><li>G-theory is a theory of reliability (dependability).</li><li>Item difficulty is part of item analysis and IRT.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cronbach, Gleser, Nanda and Rajaratnam, The Dependability of Behavioral Measurements (1972).</li><li>The G-study estimates variance components; the D-study plans the best design.</li><li>The generalizability coefficient is the G-theory version of reliability.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 46, "question": "In psychoanalytic therapy, ‘working through’ refers to:", "options": ["The first sudden moment of insight", "Emotional release by reliving a past event", "The planned ending phase of therapy", "Repeatedly exploring an insight until it produces lasting change"], "correctAnswer": 3, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Working through is the slow, repeated exploration of the same conflict in many forms, so that intellectual insight becomes emotional and behavioural change.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A sudden insight is not enough on its own; working through follows it.</li><li>Emotional release by reliving events is catharsis or abreaction.</li><li>The ending phase is termination.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Freud, ‘Remembering, Repeating and Working-Through’ (1914).</li><li>Insight alone is ‘intellectual insight’; change needs ‘emotional insight’.</li><li>The ‘corrective emotional experience’ was Franz Alexander’s idea.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 47, "question": "Varimax rotation in factor analysis produces factors that are:", "options": ["Unrotated principal components", "Oblique (correlated)", "Orthogonal (uncorrelated)", "Hierarchical (second-order)"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Varimax (Kaiser, 1958) is an orthogonal rotation: it keeps factors at right angles (uncorrelated) while maximising the variance of loadings, so each variable loads strongly on few factors.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Oblique rotations such as oblimin and promax allow factors to correlate.</li><li>Second-order factors come from factoring correlated (oblique) factors.</li><li>Rotation changes the unrotated solution to make it easier to interpret.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Thurstone’s ‘simple structure’ is the goal of rotation.</li><li>Exploratory factor analysis finds structure; confirmatory factor analysis tests a set model.</li><li>IMHANS 2025 had an Assertion–Reason item on factor analysis identifying latent variables.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IMHANS 2025, RINPAS 2024, NIMHANS 2023 (memory-based), IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 48, "question": "Adrian Wells’ metacognitive therapy mainly targets:", "options": ["Beliefs about thinking, such as ‘worrying keeps me safe’", "Values and committed action", "Early maladaptive schemas from childhood", "The content of negative automatic thoughts"], "correctAnswer": 0, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Metacognitive therapy works on beliefs ABOUT thoughts (positive: ‘worry helps me cope’; negative: ‘worry is uncontrollable and dangerous’) and on the ‘cognitive attentional syndrome’ of worry, rumination and threat monitoring.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The content of automatic thoughts is the target of Beck’s cognitive therapy.</li><li>Early maladaptive schemas are targeted in Young’s schema therapy.</li><li>Values and committed action belong to ACT.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Wells’ model of GAD: Type 1 worry (everyday) and Type 2 worry (‘worry about worry’).</li><li>Attention training technique (ATT) and detached mindfulness are MCT techniques.</li><li>Metacognition = thinking about one’s own thinking (JEMAS 2022 asked the term).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — JEMAS 2024, RML 2022, JEMAS 2022, M.Phil Entrance 2021. We recommend you keep this area ready."}, {"id": 49, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2025</span>Which of the following is considered the greatest methodological risk in computer-adaptive psychological testing compared to traditional paper-pencil testing?", "options": ["Ceiling and floor effects in the test design", "Reduced standardisation across administrations", "Item exposure and compromised test security due to adaptive algorithms", "Increased examiner bias in scoring responses"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Adaptive algorithms keep choosing the most informative items, so some items are shown very often. Over-exposed items can leak, so test security and item-bank maintenance become the main risk.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>CAT actually reduces ceiling and floor effects by matching items to ability.</li><li>Administration is computer-controlled and standardised.</li><li>Scoring is automatic, so examiner bias is lower.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Exposure-control methods (e.g. Sympson–Hetter) limit how often an item appears.</li><li>CAT needs a large, IRT-calibrated item bank.</li><li>GRE and NCLEX have used computerised adaptive testing.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 50, "question": "The ‘downward arrow technique’ in CBT is used to:", "options": ["Lower arousal through slow breathing", "Rank feared situations from least to most", "Rate anxiety on a 0–100 scale", "Uncover the core belief beneath an automatic thought"], "correctAnswer": 3, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The therapist keeps asking ‘If that were true, what would it mean about you?’ to move down from a surface thought to the underlying core belief.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Slow breathing is a relaxation skill.</li><li>Rating anxiety 0–100 uses SUDS.</li><li>Ranking feared situations builds an exposure hierarchy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>David Burns popularised the downward arrow technique.</li><li>Thought records have columns for situation, emotion, automatic thought, evidence and balanced thought.</li><li>Socratic questioning is the general method behind it.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 51, "question": "A PTSD client writes an ‘impact statement’ on how the assault changed her beliefs about safety, trust and self-blame, and the therapist challenges her ‘stuck points’. This therapy is:", "options": ["Psychological first aid", "EMDR", "Prolonged exposure", "Cognitive processing therapy"], "correctAnswer": 3, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Cognitive processing therapy (Resick) uses an impact statement and worksheets to identify and challenge ‘stuck points’ — beliefs such as self-blame that keep PTSD going.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Prolonged exposure focuses on repeated imaginal and in-vivo exposure to the memory and reminders.</li><li>EMDR uses bilateral stimulation while recalling the memory.</li><li>Psychological first aid is early, practical support after a disaster, not a PTSD therapy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>CPT themes: safety, trust, power/control, esteem and intimacy.</li><li>GMCH 2023 asked about the management of PTSD once it is diagnosed.</li><li>Trauma-focused CBT (TF-CBT) is the main approach for children.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IHBAS 2025, IHBAS 2024, GMCH 2023, RML 2022, Gurugram. We recommend you keep this area ready."}, {"id": 52, "question": "The ‘Dodo bird verdict’ in psychotherapy research means that:", "options": ["Different genuine therapies tend to give roughly equal outcomes", "Only cognitive behaviour therapy is effective", "Therapy is no better than a placebo", "Longer therapy always gives better results"], "correctAnswer": 0, "subject": "Therapy research & history", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> From Alice in Wonderland (‘Everybody has won, and all must have prizes’), Rosenzweig (1936) and later Luborsky (1975) suggested that bona fide therapies produce similar benefits, pointing to common factors.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The verdict says therapies work about equally — not that they are no better than placebo.</li><li>It argues against any single therapy being the only effective one.</li><li>It says nothing about longer therapy always being better.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Common factors: therapeutic alliance, empathy, expectation of change, a rationale and a ritual (Jerome Frank).</li><li>Bruce Wampold’s ‘contextual model’ supports common factors.</li><li>Critics note that specific treatments still matter for some disorders, e.g. exposure for OCD.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 53, "question": "Morita therapy, which begins with a period of absolute bed rest and teaches accepting feelings ‘as they are’ while doing what needs to be done, originated in:", "options": ["India", "Japan", "Korea", "China"], "correctAnswer": 1, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Shoma Morita developed Morita therapy in Japan around 1919 for ‘shinkeishitsu’ (anxious, perfectionistic nervousness). It draws on Zen ideas of acceptance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>India’s indigenous approaches include yoga, meditation and the guru–chela model.</li><li>China – not the origin of Morita therapy.</li><li>Korea – not the origin of Morita therapy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Naikan therapy (Yoshimoto Ishin) is another Japanese therapy, based on structured self-reflection.</li><li>Morita’s phrase arugamama means ‘accepting things as they are’.</li><li>Morita therapy is often compared with ACT.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 54, "question": "<span class=\"pyq-badge\">PYQ · JEMAS 2022 &amp; JEMAS 2024</span>‘Dereflection’ is a component of:", "options": ["Existential therapy", "Person-centred therapy", "Logotherapy", "Gestalt therapy"], "correctAnswer": 2, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Viktor Frankl’s logotherapy uses dereflection: turning the client’s excessive attention (hyper-reflection) away from the problem and towards meaningful goals and other people.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Existential therapy is the broad family; dereflection is specific to logotherapy.</li><li>Person-centred therapy (Rogers) relies on the core conditions.</li><li>Gestalt therapy (Perls) uses awareness, the empty chair and ‘here and now’.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2022 asked who developed logotherapy (Viktor Frankl).</li><li>Paradoxical intention is logotherapy’s other main technique.</li><li>Frankl’s book: Man’s Search for Meaning (1946).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 55, "question": "Stress inoculation training, with conceptualisation, skill-acquisition and application phases, was developed by:", "options": ["Donald Meichenbaum", "Richard Lazarus", "Albert Ellis", "Arnold Lazarus"], "correctAnswer": 0, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Donald Meichenbaum developed stress inoculation training (1970s): like a vaccine, clients practise coping skills against small doses of stress before facing larger ones.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Albert Ellis – REBT.</li><li>Arnold Lazarus – multimodal therapy (BASIC ID).</li><li>Richard Lazarus – the transactional model of stress and appraisal, not this therapy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Meichenbaum also developed self-instructional training (with Goodman, 1971).</li><li>Cognitive behaviour modification = Meichenbaum’s broad approach.</li><li>The phases: conceptualisation → skill acquisition and rehearsal → application and follow-through.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 56, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Interpretation of the transference is a central technique of psychoanalytic therapy.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">In transference the client redirects feelings from important past figures onto the therapist, so old conflicts can be worked on in the present.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true and R explains A: because past conflicts come alive in the relationship with the therapist, interpreting the transference lets the client see and change them ‘here and now’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>B is wrong because R does explain A.</li><li>C and D are wrong because both statements are true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Transference neurosis – an intense version of the client’s core conflicts focused on the analyst.</li><li>Freud first saw transference as an obstacle, later as the main tool of therapy.</li><li>IHBAS 2024 asked about countertransference.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IHBAS 2024, NFSU 2023, RML 2022, JEMAS 2022. We recommend you keep this area ready."}, {"id": 57, "question": "A test has a true-score variance of 64 and an error variance of 16. Its reliability coefficient is:", "options": ["0.20", "0.25", "0.80", "4.00"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Reliability = true variance ÷ observed variance, where observed variance = true + error = 64 + 16 = 80. So reliability = 64 ÷ 80 = 0.80.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>0.20 = error ÷ observed (16 ÷ 80) — this is the error proportion, i.e. 1 – reliability.</li><li>0.25 = error ÷ true (16 ÷ 64).</li><li>4.00 = true ÷ error (64 ÷ 16); reliability can never exceed 1.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS Paper-II and J&amp;K 2023 asked how reliability is defined in terms of variance.</li><li>Classical test theory: X = T + E (observed = true + error).</li><li>SEM = SD × √(1 – r).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — J&amp;K 2023, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 58, "question": "In Beck’s cognitive therapy, the stance in which therapist and client work together to test the client’s beliefs like co-scientists is called:", "options": ["Disputation", "Guided discovery", "Free association", "Collaborative empiricism"], "correctAnswer": 3, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Collaborative empiricism means therapist and client are a team, treating thoughts as hypotheses to be checked against evidence.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Guided discovery is the questioning process (Socratic questions) that helps the client reach his own conclusions — it works within collaborative empiricism.</li><li>Disputation is Ellis’s more direct, persuasive REBT style.</li><li>Free association is psychoanalytic.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>GMCH 2023 asked who first developed CBT (Beck).</li><li>GBU 2025 asked which method Beck’s therapy uses (objective assessment of beliefs).</li><li>Sessions are structured: agenda, review of homework, new homework.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>10 of them</b> (recent examples: IHBAS 2025, GBU 2025, JEMAS 2024, NFSU 2023). We recommend you focus on this area."}, {"id": 59, "question": "Which of the following is NOT one of John Gottman’s ‘Four Horsemen’ that predict relationship breakdown?", "options": ["Stonewalling", "Contempt", "Criticism", "Jealousy"], "correctAnswer": 3, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Gottman’s Four Horsemen are criticism, contempt, defensiveness and stonewalling; contempt is the strongest predictor of divorce. Jealousy is not one of them.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Criticism is one of the four.</li><li>Contempt is one of the four — the most damaging.</li><li>Stonewalling (withdrawing from interaction) is one of the four.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Antidotes: gentle start-up, building appreciation, taking responsibility, self-soothing.</li><li>Emotionally focused couple therapy (Sue Johnson) is based on attachment theory.</li><li>Integrative behavioural couple therapy (Jacobson and Christensen) adds acceptance work.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 60, "question": "The ‘triangle of conflict’ (defence–anxiety–hidden feeling) and the ‘triangle of person’ (therapist–current–past) were described by:", "options": ["James Mann", "David Malan", "Peter Sifneos", "Michael Balint"], "correctAnswer": 1, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> David Malan’s two triangles guide brief dynamic therapy: the therapist links the client’s defences and anxiety to hidden feelings, and connects patterns with the therapist, current people and past figures.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Peter Sifneos – short-term anxiety-provoking psychotherapy (STAPP).</li><li>James Mann – time-limited (12-session) psychotherapy.</li><li>Michael Balint – focal therapy (with Malan at the Tavistock) and the ‘basic fault’, but not the triangles.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Habib Davanloo built intensive short-term dynamic psychotherapy (ISTDP) on Malan’s triangles.</li><li>Brief dynamic therapies select a ‘focus’ and are time-limited.</li><li>Malan, Individual Psychotherapy and the Science of Psychodynamics (1979).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — JEMAS 2024, JEMAS 2022. We recommend you keep this area ready."}, {"id": 61, "question": "Compassion-focused therapy, built around three emotion-regulation systems (threat, drive and soothing), was developed by:", "options": ["Adrian Wells", "Kristin Neff", "Paul Gilbert", "Jon Kabat-Zinn"], "correctAnswer": 2, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Paul Gilbert developed compassion-focused therapy for people with high shame and self-criticism. It aims to strengthen the soothing (affiliative) system.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Kristin Neff researched self-compassion and built the Self-Compassion Scale, but did not develop CFT.</li><li>Jon Kabat-Zinn – MBSR.</li><li>Adrian Wells – metacognitive therapy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Compassionate mind training is the core practice of CFT.</li><li>Neff’s three parts of self-compassion: self-kindness, common humanity, mindfulness.</li><li>CFT draws on evolutionary psychology and attachment theory.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 62, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2025</span>When a counsellor uses paraphrasing as an active listening skill, the primary goal is to:", "options": ["Interpret the hidden meaning behind the client’s statement", "Repeat the client’s exact words to ensure accuracy", "Restate the client’s message in the counsellor’s own words to check understanding and show empathy", "Provide advice based on the client’s expressed concern"], "correctAnswer": 2, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Paraphrasing restates the content of what the client said in fresh words. It shows the counsellor is listening and lets the client correct any misunderstanding.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Finding hidden meaning is interpretation.</li><li>Repeating exact words is parroting, not paraphrasing.</li><li>Giving advice is not a listening skill.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Reflection of feeling targets emotions; paraphrasing targets content.</li><li>Summarising pulls together several points at the end of a section or session.</li><li>Allen Ivey’s ‘microskills’ hierarchy organises these counselling skills.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 63, "question": "A therapist draws a three-generation family diagram showing marriages, deaths, conflicts and close alliances. This tool is the:", "options": ["Genogram", "Family sculpture", "Ecomap", "Sociogram"], "correctAnswer": 0, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A genogram is a family tree with extra information on relationships and patterns across at least three generations. It is linked with Bowen’s family systems therapy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A sociogram (Moreno) maps choices and relationships within a group.</li><li>Family sculpture is an action technique where members physically position each other.</li><li>An ecomap shows the family’s links with outside systems such as school, work and services.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>McGoldrick and Gerson standardised genogram symbols.</li><li>Genograms help spot multigenerational transmission of problems.</li><li>J&amp;K 2023 asked which technique is mainly used in family therapy.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — J&amp;K 2023, IMHANS 2021, Gurugram. We recommend you keep this area ready."}, {"id": 64, "question": "In narrative therapy (White and Epston), ‘externalising the problem’ means:", "options": ["Helping the client blame other people", "Giving homework to be done outside sessions", "Expressing anger outwardly instead of holding it in", "Talking about the problem as separate from the person"], "correctAnswer": 3, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Externalising separates the person from the problem — ‘the person is not the problem; the problem is the problem’ — e.g. talking about how ‘Anxiety’ bullies the client. This opens space for a new, preferred life story.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>It is not about shifting blame onto others.</li><li>Venting anger is catharsis, not externalising.</li><li>Homework is part of CBT, not the meaning of externalising.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Michael White and David Epston, Narrative Means to Therapeutic Ends (1990).</li><li>‘Unique outcomes’ are times the problem did not win.</li><li>Narrative therapy comes from social constructionism.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 65, "question": "A screening test for depression rarely misses true cases, but it also flags many healthy people as positive. This test has:", "options": ["High sensitivity and high specificity", "High sensitivity and low specificity", "Low sensitivity and high specificity", "Low sensitivity and low specificity"], "correctAnswer": 1, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Sensitivity = ability to detect true cases (few false negatives). Specificity = ability to correctly clear people without the condition (few false positives). Many false positives means low specificity.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Low sensitivity would mean it misses many true cases.</li><li>High specificity would mean few false positives.</li><li>‘Low on both’ contradicts the fact that it rarely misses cases.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>GMCH 2023 asked how sensitivity is defined (correctly identifying cases).</li><li>Screening tests prefer high sensitivity; confirmatory tests prefer high specificity.</li><li>The ROC curve plots sensitivity against 1 – specificity.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IHBAS 2024, J&amp;K 2023, GMCH 2023, JEMAS 2022, IMHANS 2021. We recommend you keep this area ready."}, {"id": 66, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Time-out is a form of positive punishment.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">Time-out removes the child from access to reinforcement for a short period.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 3, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A is false: time-out takes away access to reinforcement, so it is negative punishment (removing something pleasant), not positive punishment (adding something unpleasant). R is true.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A and B are wrong because A is false.</li><li>C is wrong because A is false and R is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Positive punishment: adding an aversive (e.g. a reprimand).</li><li>Time-out works only if the ‘time-in’ environment is rewarding.</li><li>Response cost is the other common negative-punishment method.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — GBU 2025, RINPAS 2019. We recommend you keep this area ready."}, {"id": 67, "question": "All of the following are core processes of ACT’s ‘hexaflex’, EXCEPT:", "options": ["Distress tolerance", "Self-as-context", "Cognitive defusion", "Acceptance"], "correctAnswer": 0, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> ACT’s six processes: acceptance, cognitive defusion, contact with the present moment, self-as-context, values, and committed action. Distress tolerance is a DBT skills module.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Acceptance is an ACT process.</li><li>Cognitive defusion is an ACT process.</li><li>Self-as-context (the observing self) is an ACT process.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2024 asked which therapy has distress tolerance as a major module (DBT).</li><li>The opposite of the hexaflex (the ‘inflexahex’) shows six processes of rigidity.</li><li>Values are freely chosen life directions; goals are steps along them.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, RML 2024, RINPAS 2024). We recommend you focus on this area."}, {"id": 68, "question": "<span class=\"pyq-badge\">PYQ · IHBAS 2025</span>Systematic desensitization technique is based upon the idea of:", "options": ["Reciprocal inhibition", "Law of effect", "Habituation", "Adaptation to stress"], "correctAnswer": 0, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Joseph Wolpe (1958) built systematic desensitisation on reciprocal inhibition: a response incompatible with anxiety (deep muscle relaxation) is paired with feared stimuli, so the anxiety is inhibited.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Law of effect – Thorndike’s operant principle.</li><li>Habituation explains ERP and flooding better.</li><li>Adaptation to stress is Selye’s idea, not Wolpe’s.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Steps: relaxation training, building an anxiety hierarchy, then pairing hierarchy items with relaxation.</li><li>IHBAS 2025 also asked who proposed systematic desensitisation (Wolpe).</li><li>Wolpe, Psychotherapy by Reciprocal Inhibition (1958).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 69, "question": "James Mann’s time-limited psychotherapy is distinctive because it:", "options": ["Uses relentless pressure on defences", "Fixes therapy at 12 sessions with a set end date", "Uses free association with no time limit", "Focuses only on current relationship problems"], "correctAnswer": 1, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Mann (1973) used exactly 12 sessions with a fixed ending. The time limit itself brings up the ‘central issue’ around separation and loss, which is worked through as therapy ends.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Classical psychoanalysis is open-ended.</li><li>A focus on current relationship problems describes interpersonal psychotherapy (IPT).</li><li>Relentless pressure on defences describes Davanloo’s ISTDP.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sifneos’ STAPP selects motivated clients with a clear focus.</li><li>Brief therapies became popular because of cost and research needs.</li><li>Termination is a key therapeutic phase in time-limited therapy.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2021. We recommend you keep this area ready."}, {"id": 70, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2025</span>According to Murray Bowen’s family systems theory, which of the following best represents the concept of ‘differentiation of self’?", "options": ["The ability of family members to maintain emotional independence while staying connected to others", "The process by which unresolved parental conflicts are projected onto children", "The cycle in which marital stress contributes to child dysfunction", "The degree to which family members rigidly adhere to enmeshed boundaries"], "correctAnswer": 0, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Differentiation of self is the ability to separate thinking from feeling and to stay oneself while remaining emotionally connected to the family. Poorly differentiated people are pulled into the family’s emotional reactivity.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Projecting parental conflict onto children is the ‘family projection process’.</li><li>Marital stress causing child problems relates to triangulation and the family projection process.</li><li>Enmeshment is Minuchin’s structural concept.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other Bowen concepts: triangles, multigenerational transmission, emotional cutoff, sibling position.</li><li>Bowen used genograms to trace patterns across generations.</li><li>Triangulation: drawing a third person into a tense two-person relationship.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 71, "question": "ACT is grounded in which behavioural theory of language and cognition?", "options": ["Schema theory", "Relational frame theory", "Personal construct theory", "Information-processing theory"], "correctAnswer": 1, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Relational frame theory (Hayes and colleagues) explains how humans learn to relate words and events, which allows thoughts to cause suffering. ACT was built on it, within functional contextualism.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Personal construct theory – George Kelly.</li><li>Schema theory underlies Beck’s and Young’s therapies.</li><li>Information-processing theory is a general cognitive model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Functional contextualism is ACT’s philosophy of science.</li><li>Hayes, Strosahl and Wilson, Acceptance and Commitment Therapy (1999).</li><li>Third wave = ACT, DBT, MBCT, FAP, CFT, metacognitive therapy.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IMHANS 2025, IHBAS 2025, JEMAS 2024, GMCH 2023. We recommend you keep this area ready."}, {"id": 72, "question": "<span class=\"pyq-badge\">PYQ · IHBAS Paper-II</span>Cronbach alpha is: 1. larger than the split-half reliability coefficient  2. smaller than the reliability coefficient  3. the average of all possible split-half reliability coefficients  4. equal to the Kuder–Richardson reliability for dichotomous items", "options": ["1 only", "2 only", "3 and 4 only", "1 and 4 only"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Coefficient alpha equals the mean of all possible split-half coefficients (computed with the Rulon/Flanagan formula), and for right/wrong (dichotomous) items it is identical to KR-20.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>‘1 only’ – alpha is not always larger than a given split-half value; it is their average.</li><li>‘2 only’ – alpha is a lower bound of reliability under some assumptions, but this is not the textbook answer here.</li><li>‘1 and 4’ – statement 1 is false.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS 2025 and RINPAS 2024 asked what Cronbach’s alpha measures (internal consistency).</li><li>Alpha rises with more items and higher inter-item correlations.</li><li>Very high alpha (&gt;0.95) may mean redundant items.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 73, "question": "In Beck’s model, schemas differ from automatic thoughts because schemas are:", "options": ["Defence mechanisms of the ego", "Bodily sensations that come with emotion", "Brief thoughts that pop up in a specific situation", "Deep, stable core beliefs that shape how situations are read"], "correctAnswer": 3, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Automatic thoughts are quick, situation-specific thoughts. Schemas (core beliefs such as ‘I am unlovable’) are deeper and stable, and they produce the automatic thoughts.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Brief situation-specific thoughts are automatic thoughts.</li><li>Bodily sensations are physiological responses, not schemas.</li><li>Defence mechanisms belong to psychoanalytic theory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Levels: automatic thoughts → intermediate beliefs (rules, assumptions) → core beliefs.</li><li>Jeffrey Young’s schema therapy describes 18 early maladaptive schemas.</li><li>Cognitive therapy usually starts with automatic thoughts and moves to core beliefs.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — IMHANS 2025, IHBAS 2024, NFSU 2023. We recommend you keep this area ready."}, {"id": 74, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Split-half reliability is not appropriate for a pure speed test.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">In a speed test, item difficulty rises steadily from the first item to the last.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A is true: in a pure speed test, items are easy and scores depend on how many are attempted, so odd and even halves come out almost identical and give a falsely high coefficient. R is false: pure speed tests use uniformly easy items; rising difficulty describes a power test.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A and B are wrong because R is false.</li><li>D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2022 asked when the odd–even method of splitting a test is most appropriate.</li><li>For speed tests, use test–retest or alternate forms given separately timed.</li><li>Power tests (graded difficulty, generous time limit) are the opposite of speed tests.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — RML 2022, IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 75, "question": "In Salvador Minuchin’s structural family therapy, an ‘enmeshed’ family has:", "options": ["Clear boundaries with flexible roles", "Rigid boundaries and little emotional contact", "A child who takes over a parent’s role", "Diffuse boundaries, with members over-involved in each other’s lives"], "correctAnswer": 3, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Minuchin described a continuum from enmeshed (diffuse boundaries, too much closeness, little autonomy) to disengaged (rigid boundaries, too much distance). Healthy families have clear boundaries.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Rigid boundaries with little contact = disengaged family.</li><li>Clear, flexible boundaries are the healthy middle.</li><li>A child taking a parent’s role is ‘parentification’.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Structural techniques: joining, enactment, boundary making, reframing.</li><li>Minuchin, Families and Family Therapy (1974).</li><li>Psychosomatic families (e.g. anorexia) were described as enmeshed.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2025. We recommend you keep this area ready."}, {"id": 76, "question": "The method of ‘equal-appearing intervals’, in which judges sort attitude statements into 11 piles, was developed by:", "options": ["Rensis Likert", "Louis Thurstone", "Charles Osgood", "Louis Guttman"], "correctAnswer": 1, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Thurstone and Chave (1929) had judges place statements on an 11-point scale; each statement’s median placement became its scale value, and the respondent’s score is the median (or mean) of the statements they agree with.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Likert – summated ratings.</li><li>Guttman – cumulative (scalogram) scaling.</li><li>Osgood – semantic differential.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Thurstone also proposed the law of comparative judgement and primary mental abilities.</li><li>Thurstone scales are time-consuming because they need many judges.</li><li>The ‘Q’ value (interquartile range) shows how ambiguous a statement was.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RML 2022, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 77, "question": "Match the school of family therapy (List I) with its founder (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Structural</td><td>a. Virginia Satir</td></tr><tr><td>2. Strategic</td><td>b. Salvador Minuchin</td></tr><tr><td>3. Milan systemic</td><td>c. Mara Selvini Palazzoli</td></tr><tr><td>4. Experiential (communication)</td><td>d. Jay Haley</td></tr></tbody></table></div>", "options": ["1-d, 2-b, 3-c, 4-a", "1-b, 2-c, 3-d, 4-a", "1-b, 2-d, 3-a, 4-c", "1-b, 2-d, 3-c, 4-a"], "correctAnswer": 3, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Minuchin – structural; Haley (with Cloé Madanes) – strategic, using directives and paradox; Selvini Palazzoli and the Milan team – systemic (circular questioning, positive connotation); Satir – experiential, focusing on communication and self-esteem.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Minuchin with Haley, or Selvini Palazzoli with Satir.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Mental Research Institute (MRI, Palo Alto) – Bateson, Jackson, Watzlawick – shaped strategic therapy.</li><li>The double-bind theory came from Bateson’s Palo Alto group.</li><li>Carl Whitaker – symbolic-experiential family therapy.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — J&amp;K 2023, Gurugram. We recommend you keep this area ready."}, {"id": 78, "question": "A child loses 2 stars from his star chart every time he hits his sister. This technique is:", "options": ["Overcorrection", "Response cost", "Extinction", "Time-out"], "correctAnswer": 1, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Response cost removes a reinforcer the child already has (stars, tokens, privileges) after a problem behaviour — a form of negative punishment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Time-out removes the child from all reinforcement for a short period.</li><li>Overcorrection makes the child restore or over-practise correct behaviour.</li><li>Extinction withholds the reinforcer that was maintaining the behaviour.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Response cost often works within a token economy.</li><li>Negative punishment = removing something pleasant; positive punishment = adding something unpleasant.</li><li>Punishment works best together with reinforcement of alternative behaviour.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: RML 2024, RINPAS 2024, JEMAS 2024, RML 2022). We recommend you focus on this area."}, {"id": 79, "question": "In ACT, ‘cognitive defusion’ means:", "options": ["Seeing thoughts as just thoughts, not literal truths", "Replacing irrational thoughts with rational ones", "Pushing unwanted thoughts out of the mind", "Tracing thoughts back to childhood events"], "correctAnswer": 0, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Defusion creates distance from thoughts — e.g. ‘I am having the thought that I am a failure’ — so they lose their grip, without arguing about whether they are true.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Replacing thoughts with rational ones is cognitive restructuring (Beck, Ellis).</li><li>Thought suppression usually makes thoughts come back more (Wegner’s white bear studies).</li><li>Tracing thoughts to childhood is psychodynamic.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cognitive fusion = being ‘stuck’ to thoughts and treating them as reality.</li><li>Defusion exercises: repeating a word until it loses meaning (Titchener’s repetition).</li><li>Experiential avoidance is the main problem ACT targets.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IMHANS 2025, IHBAS 2025, JEMAS 2024, GMCH 2023. We recommend you keep this area ready."}, {"id": 80, "question": "Arjun failed an exam (A), believes ‘I must never fail’ (B), and now feels worthless (C). An REBT therapist will mainly target:", "options": ["C – the emotional consequence", "A – the activating event", "B – the irrational belief", "E – the new effective philosophy"], "correctAnswer": 2, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> REBT holds that it is not the event (A) but the belief about it (B) that causes the consequence (C). Change comes from disputing the irrational belief.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The event usually cannot be changed and is not the main cause.</li><li>Emotions change once beliefs change; they are not targeted directly.</li><li>E is the outcome of successful disputing, not the target.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Irrational beliefs: demandingness (‘musts’), awfulising, low frustration tolerance, global self-rating.</li><li>Ellis was influenced by the Stoic Epictetus: people are disturbed by their views of things.</li><li>IMHANS 2025 asked what REBT says causes distress.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IMHANS 2025, IHBAS 2025, NIMHANS 2023 (memory-based), J&amp;K 2023. We recommend you keep this area ready."}, {"id": 81, "question": "The token economy was first used systematically on a psychiatric ward by:", "options": ["Wolpe and Lazarus", "Ayllon and Azrin", "Skinner and Lindsley", "Masters and Johnson"], "correctAnswer": 1, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Teodoro Ayllon and Nathan Azrin ran a token economy with chronic psychiatric inpatients at Anna State Hospital (1960s), described in The Token Economy (1968).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Skinner and Lindsley introduced the term ‘behaviour therapy’ (1953) and studied operant behaviour in patients.</li><li>Wolpe and Lazarus wrote on behaviour therapy techniques.</li><li>Masters and Johnson developed sex therapy.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Tokens are generalised (secondary) reinforcers exchanged for back-up rewards.</li><li>Token economies are used in schools, ADHD and institutional settings.</li><li>A key problem is generalisation once tokens are withdrawn.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — RINPAS 2024, JEMAS 2024, JEPAS 2020, RINPAS 2019, JANAS. We recommend you keep this area ready."}, {"id": 82, "question": "Arrange the steps of constructing a psychological test in the correct order: I. Item analysis on a try-out sample II. Writing the pool of items III. Defining the construct and test specifications IV. Establishing norms on the standardisation sample", "options": ["II, III, I, IV", "III, I, II, IV", "III, II, I, IV", "III, II, IV, I"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> First define what the test measures and its blueprint, then write a large item pool, then try it out and run item analysis to keep the best items, and finally standardise the final form and build norms (along with reliability and validity studies).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Items cannot be written before the construct is defined.</li><li>Item analysis needs items to exist first.</li><li>Norms come from the final form, after item analysis.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Item analysis uses the difficulty index (p) and discrimination index (D).</li><li>Write about 1.5–2 times as many items as needed for the final test.</li><li>The test manual should report norms, reliability and validity.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — NFSU 2023, RML 2022. We recommend you keep this area ready."}, {"id": 83, "question": "In a skills group, Neha learns ‘DEAR MAN’ to ask clearly for what she needs while keeping her relationships and self-respect. This belongs to which DBT module?", "options": ["Interpersonal effectiveness", "Emotion regulation", "Core mindfulness", "Distress tolerance"], "correctAnswer": 0, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> DEAR MAN (Describe, Express, Assert, Reinforce; stay Mindful, Appear confident, Negotiate) is the main interpersonal effectiveness skill in Linehan’s DBT.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Distress tolerance – surviving crises without making them worse (e.g. TIPP, ACCEPTS).</li><li>Emotion regulation – understanding and changing emotions (e.g. opposite action).</li><li>Core mindfulness – ‘what’ and ‘how’ skills, wise mind.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2024 asked which therapy has distress tolerance as a major module (DBT).</li><li>IMHANS 2025 had an Assertion–Reason item on DBT for borderline personality disorder.</li><li>DBT has individual therapy, skills group, phone coaching and a therapist consultation team.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, RML 2024, RINPAS 2024). We recommend you focus on this area."}, {"id": 84, "question": "Differential item functioning (DIF) is present when:", "options": ["An item discriminates poorly in every group", "An item is very easy for everyone", "Two groups differ in their average total score", "People of equal ability from different groups have different chances of passing an item"], "correctAnswer": 3, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> DIF means an item behaves differently for groups (e.g. gender, language) even after matching people on the ability being measured — a possible sign of item bias.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A difference in group means alone is ‘impact’, not DIF — the groups may truly differ.</li><li>An easy item has a high p-value; that is not DIF.</li><li>Poor discrimination for everyone is a general item flaw, not DIF.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Mantel–Haenszel and IRT methods are used to detect DIF.</li><li>Uniform DIF: the gap is the same at all ability levels; non-uniform DIF: it changes with ability.</li><li>Test fairness is a major issue for tests adapted to Indian languages.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 85, "question": "Arrange Freud’s therapeutic methods in the order in which he used them: I. Free association II. Hypnosis (with Breuer) III. Pressure (concentration) technique", "options": ["III, II, I", "II, III, I", "II, I, III", "I, II, III"], "correctAnswer": 1, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Freud first used hypnosis with Breuer, then the ‘pressure technique’ (pressing the forehead and insisting memories would come), and finally free association, which became the basis of psychoanalysis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Free association came last, so it cannot be first; the pressure technique came between hypnosis and free association.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Freud gave up hypnosis because not all patients could be hypnotised.</li><li>The Interpretation of Dreams was published in 1899/1900.</li><li>Charcot’s demonstrations of hypnosis in Paris influenced the young Freud.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: IHBAS 2025, GBU 2025, JEMAS 2024, IHBAS 2024). We recommend you focus on this area."}, {"id": 86, "question": "<span class=\"pyq-badge\">PYQ · JEMAS 2024</span>Which of the following is NOT a specific problem area addressed in Interpersonal Psychotherapy (IPT)?", "options": ["Interpersonal effectiveness", "Interpersonal deficits", "Interpersonal role disputes", "Role transition"], "correctAnswer": 0, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> IPT (Klerman and Weissman) focuses on four problem areas: grief, interpersonal role disputes, role transitions and interpersonal deficits. ‘Interpersonal effectiveness’ is a DBT skills module.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Interpersonal deficits (social isolation) is an IPT area.</li><li>Role disputes (conflicts with significant others) is an IPT area.</li><li>Role transitions (e.g. job loss, becoming a parent) is an IPT area.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IPT is time-limited (about 12–16 sessions) and was first developed for depression.</li><li>IPT links symptoms to current relationships, not childhood conflicts.</li><li>Grief in IPT means complicated bereavement after a death.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 87, "question": "Match the cognitive distortion (List I) with its example (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Dichotomous thinking</td><td>a. ‘This small mistake will ruin my whole career.’</td></tr><tr><td>2. Personalisation</td><td>b. ‘If I’m not perfect, I’m a total failure.’</td></tr><tr><td>3. Arbitrary inference (mind reading)</td><td>c. ‘She didn’t reply, so she must be angry with me.’</td></tr><tr><td>4. Magnification</td><td>d. ‘Our team lost because of me.’</td></tr></tbody></table></div>", "options": ["1-b, 2-c, 3-d, 4-a", "1-a, 2-d, 3-c, 4-b", "1-d, 2-b, 3-c, 4-a", "1-b, 2-d, 3-c, 4-a"], "correctAnswer": 3, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> All-or-nothing = dichotomous thinking; blaming oneself for outside events = personalisation; jumping to a conclusion without evidence = arbitrary inference; blowing a small thing out of proportion = magnification.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap personalisation with mind reading, or dichotomous thinking with magnification.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Minimisation is the opposite of magnification (shrinking positives).</li><li>Catastrophising is an extreme form of magnification.</li><li>Labelling – ‘I’m a loser’ instead of ‘I made a mistake’.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>13 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, JEMAS 2024). We recommend you focus on this area."}, {"id": 88, "question": "A client says she worked late for months and her manager did not notice. The therapist replies, ‘You feel let down and angry that your hard work went unseen.’ This mainly shows:", "options": ["Confrontation", "Unconditional positive regard", "Accurate empathic understanding", "Interpretation"], "correctAnswer": 2, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The therapist accurately reflects the client’s feelings and their meaning from her point of view — empathic understanding, one of Rogers’ core conditions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Unconditional positive regard is accepting the client as a person, not reflecting a specific feeling.</li><li>Interpretation offers a new meaning (often unconscious) that the client has not said.</li><li>Confrontation points out contradictions in what the client says or does.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IMHANS 2025 asked what ‘unconditional positive regard’ assumes (a non-judgemental attitude).</li><li>Reflection of feeling targets emotion; paraphrasing targets content.</li><li>Carkhuff’s scales rate levels of empathy in counsellors.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>10 of them</b> (recent examples: IMHANS 2025, RML 2024, RINPAS 2024, JEMAS 2024). We recommend you focus on this area."}, {"id": 89, "question": "Edward Bordin’s (1979) model of the working alliance includes agreement on goals, agreement on tasks, and:", "options": ["The bond between client and therapist", "The transference neurosis", "Insight into childhood", "Completion of homework"], "correctAnswer": 0, "subject": "Therapy research & history", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Bordin defined the working alliance as goals, tasks and the emotional bond. Alliance strength is one of the most consistent predictors of therapy outcome across approaches.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The transference neurosis is a psychoanalytic concept, not part of Bordin’s model.</li><li>Insight is a possible outcome, not an alliance component.</li><li>Homework is a CBT method.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Working Alliance Inventory (Horvath and Greenberg) measures it.</li><li>Ruptures and repairs in the alliance are a key focus of modern research.</li><li>Greenson earlier wrote about the ‘working alliance’ in psychoanalysis.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 90, "question": "The ‘WDEP’ system (Wants, Doing, Evaluation, Planning) belongs to:", "options": ["Transactional analysis", "Logotherapy", "Solution-focused therapy", "Reality therapy"], "correctAnswer": 3, "subject": "Humanistic & existential therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Reality therapy, founded by William Glasser and based on choice theory, uses WDEP: What do you want? What are you doing? Is it helping? What is your plan? (Robert Wubbolding developed the WDEP acronym.)</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Solution-focused therapy uses the miracle question and scaling.</li><li>Transactional analysis uses ego states, transactions and games.</li><li>Logotherapy uses dereflection and paradoxical intention.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>J&amp;K 2023 asked which therapy says people are responsible for their own behaviour (reality therapy).</li><li>Choice theory: five basic needs — survival, love and belonging, power, freedom and fun.</li><li>Glasser, Reality Therapy (1965).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — J&amp;K 2023. We recommend you keep this area ready."}, {"id": 91, "question": "J.S. Neki argued that a ‘guru–chela’ model of the therapeutic relationship may suit many Indian clients because it:", "options": ["Relies mainly on free association", "Accepts greater dependence on, and guidance from, the therapist", "Avoids involving the family in treatment", "Insists on strict therapist neutrality"], "correctAnswer": 1, "subject": "Brief, trauma & other therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Neki (1973) suggested that Indian clients often expect a warm, guiding, somewhat directive relationship, like a guru with a disciple, and that healthy dependence can be therapeutic — unlike the Western emphasis on neutrality and early independence.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Strict neutrality is the classical Western psychoanalytic stance.</li><li>Indian approaches usually involve the family more, not less.</li><li>Free association is not the core of the guru–chela model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>N.S. Vahia developed a therapy based on Patanjali’s yoga.</li><li>Indian therapy often includes family members in sessions.</li><li>GBU 2025 asked how Indian psychology addresses mental health.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: GBU 2025, JEMAS 2024, IHBAS 2024, RML 2022). We recommend you focus on this area."}, {"id": 92, "question": "Match the psychometrician (List I) with the contribution (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Lee Cronbach</td><td>a. Scalogram analysis</td></tr><tr><td>2. Georg Rasch</td><td>b. Coefficient alpha</td></tr><tr><td>3. Louis Guttman</td><td>c. Two-factor theory and early factor analysis</td></tr><tr><td>4. Charles Spearman</td><td>d. One-parameter IRT model</td></tr></tbody></table></div>", "options": ["1-b, 2-a, 3-d, 4-c", "1-d, 2-b, 3-a, 4-c", "1-b, 2-d, 3-a, 4-c", "1-b, 2-d, 3-c, 4-a"], "correctAnswer": 2, "subject": "Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Cronbach introduced coefficient alpha (1951); Rasch developed the one-parameter logistic model (1960); Guttman developed scalogram analysis; Spearman proposed g and the two-factor theory (1904) and laid the base of factor analysis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Rasch with Guttman, or Guttman with Spearman.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Spearman also gave the Spearman–Brown prophecy formula and rank-order correlation.</li><li>Rasch models assume all items have equal discrimination.</li><li>IHBAS Paper-II asked how many factors Spearman proposed.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, RINPAS 2024, JEMAS 2022). We recommend you focus on this area."}, {"id": 93, "question": "In Yalom’s list of group therapeutic factors, the relief of discovering that others have similar problems is called:", "options": ["Altruism", "Instillation of hope", "Universality", "Group cohesiveness"], "correctAnswer": 2, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Universality — ‘I’m not the only one’ — reduces shame and isolation, especially early in a group.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Cohesiveness – the sense of belonging and acceptance in the group.</li><li>Instillation of hope – seeing others improve.</li><li>Altruism – the benefit of helping other members.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Yalom’s 11 factors also include imparting information, corrective recapitulation of the family group, interpersonal learning, catharsis and existential factors.</li><li>Joseph Pratt’s ‘class method’ for tuberculosis patients (1905) is often called the first group therapy.</li><li>Jacob Moreno coined ‘group psychotherapy’ and developed psychodrama.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: RML 2024, JEMAS 2024, J&amp;K 2023, GMCH 2023). We recommend you focus on this area."}, {"id": 94, "question": "Hans Eysenck’s famous 1952 review of psychotherapy outcome claimed that:", "options": ["Behaviour therapy cured almost every patient", "Therapy was harmful to most patients", "Psychoanalysis was clearly better than other therapies", "Neurotic patients improved about as much without therapy as with it"], "correctAnswer": 3, "subject": "Therapy research & history", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Eysenck argued that about two-thirds of neurotic patients improved within two years whether or not they received psychotherapy (‘spontaneous remission’). The paper triggered decades of outcome research.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>He claimed psychoanalysis did no better — even worse — than no treatment.</li><li>Behaviour therapy was only emerging in 1952.</li><li>He did not claim therapy was harmful to most patients.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Smith and Glass’s meta-analysis (1977) answered Eysenck by showing clear benefits of therapy.</li><li>Bergin later pointed to ‘deterioration effects’ in some clients.</li><li>Eysenck’s paper: ‘The effects of psychotherapy: an evaluation’ (1952).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 95, "question": "A depressed client spends most of the day in bed. The therapist first asks him to plan small activities each day and rate each for pleasure and mastery. This technique is:", "options": ["Cognitive restructuring", "Activity scheduling (behavioural activation)", "Thought stopping", "Graded exposure"], "correctAnswer": 1, "subject": "Cognitive therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Activity scheduling with pleasure and mastery ratings is the core of behavioural activation. In severe depression it usually comes before cognitive work, to break the cycle of inactivity and low mood.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Cognitive restructuring challenges thoughts directly — harder when energy is very low.</li><li>Graded exposure targets fear and avoidance in anxiety.</li><li>Thought stopping interrupts intrusive thoughts.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Lewinsohn linked depression to low rates of response-contingent positive reinforcement.</li><li>Jacobson’s component analysis (1996) found behavioural activation alone was as effective as full CBT.</li><li>Graded task assignment breaks big tasks into small steps.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — GMCH 2023. We recommend you keep this area ready."}, {"id": 96, "question": "After throwing food on the floor, a boy must clean up that mess AND wipe the entire dining area. This technique is:", "options": ["Overcorrection", "Shaping", "Time-out", "Response cost"], "correctAnswer": 0, "subject": "Behaviour therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Overcorrection (Foxx and Azrin) makes the person restore the environment to better than before (restitutional overcorrection) or repeatedly practise the right behaviour (positive practice).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Response cost removes a reinforcer such as tokens.</li><li>Time-out removes access to reinforcement for a short time.</li><li>Shaping reinforces successive approximations of a new behaviour.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Two types: restitutional overcorrection and positive-practice overcorrection.</li><li>Developed by Richard Foxx and Nathan Azrin (1972).</li><li>Used in intellectual disability and in toilet training.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 97, "question": "Smith and Glass (1977) showed that psychotherapy is effective by using which then-new method?", "options": ["Meta-analysis", "Single-case ABAB design", "Large national survey", "Randomised controlled trial"], "correctAnswer": 0, "subject": "Therapy research & history", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Gene Glass coined ‘meta-analysis’ (1976). Smith and Glass combined about 375 outcome studies and found that the average treated client was better off than about 75% of untreated people (effect size around 0.68).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>RCTs were already in use and are single studies.</li><li>Single-case designs study one person over time.</li><li>A survey was not their method.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Effect size (Cohen’s d) is the common currency of meta-analysis.</li><li>IMHANS 2025 asked about single-subject (ABAB) designs.</li><li>Seligman’s 1995 Consumer Reports survey studied therapy ‘effectiveness’ in real settings.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IMHANS 2025, IHBAS 2024. We recommend you keep this area ready."}, {"id": 98, "question": "<span class=\"pyq-badge\">PYQ · IMHANS 2025</span>‘Acceptance and Commitment Therapy (ACT)’ is a third-wave behavioural therapy that emphasises:", "options": ["Directly challenging irrational thoughts", "Changing problematic behaviours through classical conditioning", "Psychological flexibility and values-driven action", "Exploring early childhood experiences"], "correctAnswer": 2, "subject": "Third-wave therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Steven Hayes’ ACT aims at psychological flexibility: accepting difficult thoughts and feelings rather than fighting them, and acting in line with one’s values.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Directly challenging irrational thoughts is REBT/cognitive therapy.</li><li>Classical conditioning methods are first-wave behaviour therapy.</li><li>Exploring childhood is psychodynamic.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS 2025 asked which therapy is NOT third-wave CBT (psychoanalysis); JEMAS 2024 asked a similar question.</li><li>GMCH 2023 listed ACT as a psychological approach for anxiety.</li><li>ACT is pronounced as the word ‘act’, not A-C-T.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, we recommend you keep this area ready."}, {"id": 99, "question": "Virginia Satir described four unhealthy communication stances used under stress. They are:", "options": ["Pursuer, distancer, rescuer and victim", "Placating, blaming, super-reasonable and irrelevant", "Parent, Adult, Child and critic", "Enmeshed, disengaged, rigid and clear"], "correctAnswer": 1, "subject": "Family, group & couple therapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Satir’s stances: placating (pleasing others), blaming, super-reasonable or ‘computing’ (cold logic), and irrelevant or ‘distracting’. She aimed for ‘congruent’ communication.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Enmeshed/disengaged describe boundaries (Minuchin).</li><li>Pursuer–distancer is from couple therapy; rescuer–victim from Karpman’s drama triangle.</li><li>Parent, Adult and Child are Berne’s ego states.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Satir, Conjoint Family Therapy (1964) and Peoplemaking (1972).</li><li>Family sculpting is a Satir technique.</li><li>Satir emphasised self-esteem as central to family functioning.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 100, "question": "Catharsis through the ‘talking cure’ (the case of Anna O.) was first described by:", "options": ["Charcot and Janet", "Jung and Adler", "Anna Freud and Melanie Klein", "Breuer and Freud"], "correctAnswer": 3, "subject": "Psychodynamic therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Josef Breuer treated Anna O. (Bertha Pappenheim), who called it the ‘talking cure’. Breuer and Freud described the cathartic method in Studies on Hysteria (1895).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Charcot used hypnosis to study hysteria; Janet described dissociation.</li><li>Jung and Adler founded analytical and individual psychology later.</li><li>Anna Freud and Melanie Klein developed child analysis.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Anna O. also called it ‘chimney sweeping’.</li><li>Freud later moved from hypnosis to the pressure technique and then to free association.</li><li>Abreaction = emotional discharge when a repressed memory is recalled.</li><li>— End of Mock 8 —</li><li>Next: Mock 9 (13 October) — Legal aspects, RCI, DSM-5 &amp; ICD-11 codes.  Queries: team@psychlogic.in</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IMHANS 2025, RINPAS 2019. We recommend you keep this area ready."}];
